import { computed, defineAsyncComponent, defineComponent, h, resolveComponent } from 'vue'

import type { Component, PropType, SlotsType } from 'vue'
import { MarkdownDocument } from '@comark/vue'
import { pascalCase } from '@comark/vue/utils'
import type { MarkdownDocumentProps } from '@comark/vue'
import type { MarkdownDocument as ComarkMarkdownDocument } from 'comark'

// Generated by the module from `components/content/**`. Virtual imports have to be
// static for the bundler to rewrite them; the file only exists in a Nuxt build.
import { globalComponents, localComponents } from '#build/content/components.mjs'

type MarkdownDocumentValue = NonNullable<MarkdownDocumentProps['value']>
/** A Nuxt Content v3 document, as returned by `queryCollection()`: frontmatter flattened next to `body`. */
type ContentDocumentValue = { body: MarkdownDocumentValue['nodes'] } & Record<string, any>

function isMarkdownDocument(value: MarkdownDocumentValue | ContentDocumentValue): value is MarkdownDocumentValue {
  return 'nodes' in value
}

const debug = import.meta.dev || (import.meta as { preview?: boolean }).preview

type LocalComponent = Component | (() => Promise<Component | { default: Component }>)

// Lazy entries are generated as `async () => import(...)`. A plain function can't be the
// marker: functional components (e.g. from a `.ts` file) are plain functions too.
function isLazyLoader(component: LocalComponent): component is () => Promise<unknown> {
  return Object.prototype.toString.call(component) === '[object AsyncFunction]'
}

const asyncLocalComponents = new Map<string, Component>()
const asyncWrappedComponents = new WeakMap<object, Component>()

/**
 * Components with a `setup` are wrapped in an async component (cached per component),
 * so an async `setup` resolves the same way as a lazy one.
 */
function wrapComponent(component: Component): Component {
  if (typeof component !== 'object' || '__asyncLoader' in component || !('setup' in component)) {
    return component
  }
  let wrapped = asyncWrappedComponents.get(component)
  if (!wrapped) {
    wrapped = defineAsyncComponent(() => Promise.resolve(component))
    asyncWrappedComponents.set(component, wrapped)
  }
  return wrapped
}

/** Resolve a component by name: global ones from the Vue app, local ones from `components/content`. */
function resolveVueComponent(name: string): Component | undefined {
  const pascal = pascalCase(name)
  // `Prose*` first (same order as `MarkdownDocument`), so e.g. a user `ProseA` overrides the built-in `A`.
  for (const candidate of new Set([`Prose${pascal}`, pascal])) {
    if ((globalComponents as string[]).includes(candidate)) {
      // Must run during render: `resolveComponent` reads the current instance's app context.
      const component = resolveComponent(candidate, false)
      if (typeof component !== 'string') return wrapComponent(component)
    }

    const local = (localComponents as Record<string, LocalComponent>)[candidate]
    if (!local) continue
    // `*.lazy.*` entries are loaders; the async component is cached so each loads once.
    if (isLazyLoader(local)) {
      let asyncComponent = asyncLocalComponents.get(candidate)
      if (!asyncComponent) {
        asyncComponent = defineAsyncComponent(local as () => Promise<Component>)
        asyncLocalComponents.set(candidate, asyncComponent)
      }
      return asyncComponent
    }
    return wrapComponent(local)
  }
}

/** `components` prop values can be component names (`{ p: 'MyParagraph' }`); resolve them like tags. */
function resolveComponentsMap(components: Record<string, unknown> = {}) {
  const result: Record<string, unknown> = {}
  for (const [tag, component] of Object.entries(components)) {
    // Unknown names (e.g. another HTML tag such as `'div'`) are rendered as-is.
    result[tag] = typeof component === 'string' ? resolveVueComponent(component) ?? component : component
  }
  return result as MarkdownDocumentProps['components']
}

export default defineComponent({
  name: 'ComarkContent',
  props: {
    /**
     * Content to render: a Comark document (`{ nodes, frontmatter, meta }`) or a
     * document returned by `queryCollection()` (`{ body, ...frontmatter }`).
     */
    value: {
      type: Object as PropType<MarkdownDocumentValue | ContentDocumentValue>,
      default: undefined,
    },
    /**
     * Custom component mappings for element tags
     */
    components: {
      type: Object as PropType<MarkdownDocumentProps['components']>,
      default: undefined,
    },
    /**
     * Additional data made available to the rendered tree (e.g. for binding
     * frontmatter/props).
     */
    data: {
      type: Object as PropType<MarkdownDocumentProps['data']>,
      default: undefined,
    },
  },
  slots: Object as SlotsType<{
    empty?: (props: { 'data-content-id': string | undefined }) => unknown
  }>,
  setup(props, { slots }) {
    const comarkTree = computed(() => {
      if (!props.value) return undefined
      if (isMarkdownDocument(props.value)) return props.value
      const { body, id, path, ...rest } = props.value
      return {
        path,
        nodes: body,
        frontmatter: rest,
        meta: {
          id,
        },
      }
    })
    const isEmpty = computed(() => !comarkTree.value)

    return () => {
      const dataContentId = debug
        ? (comarkTree.value as ComarkMarkdownDocument)?.meta?.key
        : undefined

      if (isEmpty.value) {
        return slots.empty?.({ 'data-content-id': dataContentId }) ?? null
      }

      return h(MarkdownDocument, {
        'value': comarkTree.value!,
        'components': resolveComponentsMap(props.components),
        'componentsManifest': resolveVueComponent,
        'data': props.data,
        'data-content-id': dataContentId,
      })
    }
  },
})
